from mk import *
from lib import fbd
STRICT["on"] = True
import math
a = 6 / 2; t1 = math.sqrt(2 * 0.54 / a)

def fig():
    g = Fig(560, 260, "גוף A במסה 1.4 קילוגרם על שולחן אופקי, קשור בחוט שעובר על גלגלת למשקולת B במסה 0.6 קילוגרם, שנמצאת 0.54 מטר מעל הרצפה")
    g.ground(60, 520, 240)
    g.rect(100, 70, 300, 10, fill="url(#f-hatch)", stroke="none", width=0); g.line(100, 70, 400, 70); g.line(400, 70, 400, 240)
    g.block(200, 48, 60, 44, "M"); g.text(200, 18, "A")
    g.pulley(412, 58, 12); g.line(230, 46, 412, 46, width=1.5); g.line(424, 58, 424, 130, width=1.5)
    g.block(424, 146, 30, 30, "m"); g.text(450, 152, "B", anchor="start")
    g.dim(470, 161, 470, 240, "0.54 m")
    return g

def vgraph_a():
    g = Fig(560, 280, "גרף התשובה: המהירות של הגוף A כפונקציה של הזמן. קו ישר שעולה מאפס עד 1.8 מטר לשנייה אחרי 0.6 שניות, ואחר כך קו אופקי עד 2 שניות")
    X, Y = g.graph(70, 240, 420, 180, "t (s)", "v (m/s)", xticks=[(t, f"{t:g}") for t in (0.6, 1, 1.5, 2)], yticks=[(v, f"{v:g}") for v in (0.6, 1.2, 1.8)], xmax=2.2, ymax=2.2)
    g.plot(X, Y, [(0, 0), (0.6, 1.8), (2, 1.8)])
    g.guide(X, Y, 0.6, 1.8)
    return g

def vgraph_b():
    g = Fig(560, 260, "גרף התשובה עם חיכוך: המהירות של הגוף A כפונקציה של הזמן. קו ישר שעולה מאפס עד רגע הנחיתה של המשקולת, ואחר כך קו ישר שיורד עד אפס. בלי מספרים על הצירים")
    X, Y = g.graph(70, 220, 420, 170, "t", "v", xmax=10, ymax=1.2)
    g.plot(X, Y, [(0, 0), (4, 1), (9, 0)])
    g.line(X(4), Y(1), X(4), Y(0), stroke="var(--d-dim)", width=1, dash="4 3")
    g.heb(X(4) + 6, Y(0) + 20, "B נוחתת", anchor="middle")
    return g

E(id="bagrut-1996-q2", year=1996, label="1996 שאלה 2", topic="dynamics", sub="dyn-systems", diff=3, fig=fig,
  stem=r"גוף $A$, שמסתו $M = 1.4\,\text{kg}$, מונח על שולחן אופקי. הוא קשור בחבל, שעובר על גלגלת, למשקולת $B$ שמסתה $m = 0.6\,\text{kg}$. משחררים את המערכת ממנוחה, כשהמשקולת $B$ בגובה $0.54\,\text{m}$ מעל הרצפה. אין חיכוך בין החבל לגלגלת. בכל שלבי השאלה הגוף $A$ רחוק מאוד מהגלגלת, ולא פוגע בה.",
  parts=[
    P("א1", r"בסעיף הזה אפשר להזניח את מסת החבל ואת החיכוך בין הגוף $A$ לשולחן. כעבור כמה זמן מגיע הגוף $B$ לרצפה?", num(t1, "s"), ["fbd", "principle", "algebra"], [
        X(r"השאלה לא קבעה כיוון. לגוף A בוחרים כחיובי את הכיוון לעבר הגלגלת, ולמשקולת כלפי מטה. כך לשניהם אותה תאוצה, עם אותו סימן."),
        D(r"תרשים הכוחות על הגוף A", lambda: fbd([("T", 0, 0.8), ("N", 90, 1.0), ("Mg", -90, 1.0)], "תרשים כוחות על הגוף A: מתיחות החבל לעבר הגלגלת, הכוח הנורמלי כלפי מעלה וכוח הכובד כלפי מטה. הכיוון החיובי לעבר הגלגלת",
            positive=0, body="block", body_label="A", surface="below", note="בלי חיכוך")),
        D(r"תרשים הכוחות על המשקולת B", lambda: fbd([("T", 90, 0.8), ("mg", -90, 1.0)], "תרשים כוחות על המשקולת B: מתיחות החבל כלפי מעלה וכוח הכובד כלפי מטה. הכיוון החיובי כלפי מטה",
            positive=-90, body="block", body_label="B", note="יורדת")),
        S(r"משוואות הכוחות", r"לגוף A: בכיוון החיובי רק המתיחות. למשקולת: בכיוון החיובי המשקל, ונגדו המתיחות", r"T = Ma \qquad mg - T = ma", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מחברים", r"המתיחות מתבטלת", r"mg = (M + m)\,a"),
        S(r"מחלקים את משוואת הכוחות במסה", r"מחלקים במסה הכוללת", r"a = \frac{0.6 \cdot 10}{1.4 + 0.6} = 3\,\text{m/s}^2"),
        S(r"משוואת המקום של המשקולת", r"היא יוצאת ממנוחה ויורדת את הגובה הנתון", r"0.54 = 0 + 0 \cdot t + \tfrac{1}{2} \cdot 3\,t^2", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"מבודדים את הזמן", r"מכפילים בשתיים, מחלקים בשלוש ומוציאים שורש", r"t^2 = \frac{2 \cdot 0.54}{3} = 0.36 \;\Rightarrow\; t = 0.6\,\text{s}"),
    ], r"$0.6\,\text{s}$", key=r"0.6 s"),
    P("א2", r"שרטטו גרף של המהירות של הגוף $A$ כפונקציה של הזמן, מרגע השחרור ($t = 0$) עד הרגע $t = 2\,\text{s}$.", OPEN, ["graph", "principle"], [
        S(r"עד שהמשקולת נוגעת ברצפה", r"תאוצה קבועה מסעיף א1, מאפס", r"v(0.6) = 0 + 3 \cdot 0.6 = 1.8\,\text{m/s}", eq=r"v = v_0 + at"),
        D(r"אחרי שהמשקולת נוחתת: תרשים הכוחות על הגוף A", lambda: fbd([("N", 90, 1.0), ("Mg", -90, 1.0)], "תרשים כוחות על הגוף A אחרי שהמשקולת נוחתת: רק הכוח הנורמלי והכובד. החבל רפוי. הכיוון החיובי לעבר הגלגלת",
            positive=0, body="block", body_label="A", surface="below", note="החבל רפוי")),
        S(r"משוואת כוחות אחרי הנחיתה", r"החבל רפוי, ובציר האופקי אין אף כוח. לכן אין תאוצה, והמהירות נשארת קבועה", r"0 = Ma \;\Rightarrow\; v = 1.8\,\text{m/s}", eq=r"\Sigma\vec F = m\vec a"),
        D(r"הגרף: המהירות של הגוף A כפונקציה של הזמן", vgraph_a),
    ], r"קו ישר שעולה עד $1.8\,\text{m/s}$ אחרי $0.6\,\text{s}$, ואחר כך קו אופקי"),
    P("ב", r"בסעיף הזה מסת החבל זניחה, אבל יש חיכוך בין הגוף $A$ למשטח. שרטטו גרף מקורב של המהירות של הגוף $A$ כפונקציה של הזמן, מ-$t = 0$ עד שהגוף $A$ נעצר. הסבירו. אין צורך לרשום מספרים על הצירים.", OPEN, ["graph", "principle"], [
        D(r"לפני הנחיתה: תרשים הכוחות על הגוף A", lambda: fbd([("T", 0, 0.8), ("fₖ", 180, 0.4), ("N", 90, 1.0), ("Mg", -90, 1.0)], "תרשים כוחות על הגוף A לפני שהמשקולת נוחתת: מתיחות החבל לעבר הגלגלת, חיכוך נגד התנועה, הכוח הנורמלי והכובד. הכיוון החיובי לעבר הגלגלת",
            positive=0, body="block", body_label="A", surface="below", note="יש חיכוך")),
        S(r"לפני שהמשקולת נוחתת", r"החיכוך מקטין את הכוח המניע, ולכן התאוצה קבועה וקטנה יותר: קו ישר עולה, פחות תלול", r"mg - f_k = (M + m)\,a_1", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מציבים את החיכוך", r"החיכוך הקינטי הוא מקדם החיכוך כפול הכוח הנורמלי, שווה למשקל של הגוף A", r"f_k = \mu N = \mu Mg \;\Rightarrow\; mg - \mu Mg = (M + m)\,a_1"),
        D(r"אחרי הנחיתה: תרשים הכוחות על הגוף A", lambda: fbd([("fₖ", 180, 0.4), ("N", 90, 1.0), ("Mg", -90, 1.0)], "תרשים כוחות על הגוף A אחרי שהמשקולת נוחתת: רק חיכוך נגד התנועה, הכוח הנורמלי והכובד. הכיוון החיובי לעבר הגלגלת",
            positive=0, body="block", body_label="A", surface="below", note="החבל רפוי")),
        S(r"אחרי שהמשקולת נוחתת", r"החבל רפוי, ונשאר רק החיכוך נגד התנועה. התאוצה קבועה ושלילית: קו ישר יורד עד אפס", r"0 - f_k = M a_2 \;\Rightarrow\; -\mu Mg = M a_2 \;\Rightarrow\; a_2 = -\mu g"),
        D(r"הגרף: המהירות של הגוף A כפונקציה של הזמן, עם חיכוך", vgraph_b),
    ], r"משולש: עלייה בקו ישר, ואחר כך ירידה בקו ישר עד עצירה"),
    P("ג", r"בסעיף הזה אין חיכוך בין הגוף $A$ לשולחן, אבל אי אפשר להזניח את מסת החבל. איזו תנועה עושה הגוף $A$ לפני שהגוף $B$ מגיע לרצפה: במהירות קבועה, בתאוצה קבועה, בתאוצה שהולכת וגדלה, או בתאוצה שהולכת וקטנה? נמקו.", choice(["מהירות קבועה", "תאוצה קבועה", "תאוצה הולכת וגדלה", "תאוצה הולכת וקטנה"], 2), ["principle"], [
        S(r"מה מניע את המערכת", r"המשקל של המשקולת, ועוד המשקל של החלק של החבל שתלוי מתחת לגלגלת. נסמן את המסה של כל מטר חבל באות למדא, ואת אורך החלק התלוי באות y. החלק הזה מתארך ככל שהמשקולת יורדת", r"F = (m + \lambda y)\,g\ \uparrow"),
        S(r"המסה שמאיצים", r"כל החבל ושני הגופים נעים יחד, והמסה הכוללת, כולל מסת החבל, לא משתנה. לכן התאוצה גדלה", r"a = \frac{(m + \lambda y)\,g}{M + m + m_r}\ \uparrow", eq=r"\Sigma\vec F = m\vec a"),
    ], r"בתאוצה שהולכת וגדלה", key=r"התאוצה הולכת וגדלה"),
  ],
  concepts=["מערכת גופים", "גלגלת", "חבל רפוי", "חיכוך", "חבל בעל מסה"],
  summary=r"גוף על שולחן ומשקולת תלויה: זמן הירידה, מה קורה כשהמשקולת נוחתת, ואיך חיכוך ומסת החבל משנים את התנועה.",
  review="הנחה שלי.\nבמקור יש סעיפים א(1) ו-א(2), וכך גם אצלנו. בגרף של סעיף ב אין מספרים, כמו שהשאלה מבקשת.\nמה לבדוק: רק לאשר.")
